import { course } from './build.js';
const GUIDE='https://hosa.org/wp-content/uploads/2026/08/Nut-26-27.pdf';
const lessons=[];
function add(title,hook,sections,terms,caseStudy,questions,activity,source) {
 const mcqs=questions.concat(terms.slice(0,8-questions.length).map((r,i)=>[`Which explanation best describes ${r[0].toLowerCase()}?`,[r[1],...terms.filter((_,j)=>j!==i).slice(0,3).map(x=>x[1])],r[1]]));
 lessons.push({title,hook,objectives:[`Explain the mechanisms behind ${title.toLowerCase()}.`,'Compare related concepts using evidence and context.','Apply the lesson to a nutrition case without prescribing an individualized treatment.'],sections:[...sections.map(([h,p])=>[h,[p]]),['Concepts to connect',[{t:'table',head:['Concept','Meaning in practice'],rows:terms},{t:'w',kind:'match',title:'Connect each concept with its meaning',pairs:terms.slice(0,5)},activity]],['Worked application',[{t:'example',prompt:caseStudy[0],steps:caseStudy[1],answer:caseStudy[2]}]]],terms,takeaways:terms.slice(0,3).map(t=>`${t[0]}: ${t[1]}`),mcqs,frq:{prompt:caseStudy[0]+' Explain the mechanism, identify relevant contextual information, and justify your conclusion.',rubric:caseStudy[3],model:caseStudy[1].join(' ')+' '+caseStudy[2]},sources:[['HOSA Nutrition 2026–27 guidelines and official textbooks',GUIDE],['NIH Office of Dietary Supplements: nutrient fact sheets','https://ods.od.nih.gov/factsheets/list-all/'],source||['OpenStax Anatomy and Physiology 2e: nutrition and energy production','https://openstax.org/books/anatomy-and-physiology-2e/pages/24-7-nutrition-and-diet'] ]});
}

add('Foodborne illness, allergy, intolerance, and safe handling','Milk allergy and lactose intolerance can both lead someone to avoid milk, but the mechanisms differ. A lactose-free product may still contain milk protein, making the distinction practically important.',[
 ['Separate immune reactions from digestion problems','A food allergy involves an immune response to a food component, usually a protein. Reactions vary in presentation and can be severe. Intolerance does not necessarily involve that immune mechanism. Lactose intolerance results from insufficient digestion of lactose, the milk sugar, often because of reduced lactase activity. Undigested lactose can draw water into the intestine and be fermented, producing gas and other symptoms. Celiac disease is an immune-mediated disorder triggered by gluten in susceptible people and can damage intestinal tissue; it is not simply a preference or ordinary lactose intolerance. Similar symptoms do not prove the same cause. A diagnosis requires appropriate assessment, and a classroom tasting experiment should never be used to determine whether an allergy is real.'],
 ['Cross-contact is different from microbial contamination','Allergen cross-contact occurs when an allergenic food component is unintentionally transferred to another food, utensil, or surface. A food can lack an intentional allergenic ingredient yet still contain it through shared equipment. Read ingredient and allergen information each time because formulations can change. Cooking does not reliably remove every allergen. A lactose-free milk product may still contain milk proteins and therefore is not automatically appropriate for milk allergy. Microbial cross-contamination involves transfer of organisms, such as from raw food to ready-to-eat food. The two hazards may require overlapping cleaning and separation practices, but the mechanisms differ. A food handler must identify which risk is being controlled rather than treating all unwanted exposure as the same problem.'],
 ['Infection and intoxication','Foodborne infection occurs when ingested organisms establish infection or cause harm through processes in the body. Foodborne intoxication can result from toxins already present in food. Some illnesses involve both growth and toxin production, so broad categories are learning aids rather than perfect labels for every pathogen. A food can appear, smell, and taste normal yet be unsafe. Cooking may kill organisms without destroying every preformed toxin. Time, temperature, moisture, food composition, and handling affect risk. Higher-risk groups can include very young or older people, pregnant people, and people with impaired immune function, depending on the organism. Do not assume that a familiar food or a trusted appearance eliminates the need for safe handling.'],
 ['Control the chain of contamination','Safe food handling combines cleaning, separation, appropriate cooking, and timely chilling. Hands, utensils, surfaces, and storage containers can transfer organisms. Raw animal foods should not contaminate foods that will be eaten without further cooking. A food thermometer measures internal temperature more reliably than color alone. Refrigeration slows growth but does not sterilize food, and freezing does not reliably kill every organism. Thawing and reheating require appropriate procedures rather than prolonged room-temperature exposure. Use current official guidance for food-specific temperatures and storage times instead of inventing one number for all foods. The underlying reasoning is to reduce transfer, prevent excessive growth, and apply an effective control step where appropriate. Multiple controls work together; one does not automatically compensate for failure of another.'],
 ['Interpret a case without jumping to a cause','If several people become ill after a shared meal, the meal is an important clue but not proof of a particular pathogen. Timing, symptoms, foods eaten, preparation methods, and other exposures help an investigation. If only one person reacts, allergy, intolerance, infection, and unrelated causes remain possible depending on the pattern. Severe or rapidly progressive symptoms need urgent care, but the lesson’s purpose is mechanism recognition rather than individual treatment. Document what is known and what remains uncertain. A useful response identifies the suspected hazard, explains why a control would address it, and avoids making unsupported claims from appearance or one symptom. This approach transfers from food safety questions to broader clinical reasoning.']
],[['Food allergy','An immune response to a food component. It differs mechanistically from a digestive enzyme deficiency and may require strict avoidance and an individualized emergency plan.'],['Lactose intolerance','Symptoms associated with impaired lactose digestion, often due to reduced lactase. It concerns milk sugar rather than an immune response to milk protein.'],['Celiac disease','An immune-mediated response to gluten in susceptible people that can injure intestinal tissue. It is not simply a general dislike of grain products.'],['Cross-contact','Unintentional transfer of an allergenic component to another food or surface. Cooking or removing a visible ingredient may not eliminate the allergen.'],['Cross-contamination','Transfer of microorganisms between foods, surfaces, hands, or equipment. Separating raw and ready-to-eat handling is one important control.'],['Foodborne intoxication','Illness caused by toxin in food. Killing organisms during later heating does not necessarily eliminate every toxin already produced.'],['Cold storage','A control that slows microbial growth under appropriate conditions. Refrigeration does not sterilize food or make every storage duration safe.'],['Internal temperature','A measurement used to assess adequate cooking or reheating for the specific food. Surface color alone is not a reliable substitute.']],['A student serves lactose-free milk to a person with milk allergy and uses the same unwashed board for raw chicken and salad. Identify the two different hazards and explain why the apparent precautions are insufficient.',['Lactose-free milk can still contain milk proteins, which are relevant to milk allergy.','The shared board can transfer microorganisms from raw chicken to a ready-to-eat salad.','Allergen management requires checking ingredients and cross-contact, while microbial safety requires effective separation and cleaning.'],'The hazards involve different mechanisms. Removing lactose does not remove all milk allergens, and a salad that looks clean can still carry transferred organisms.',[['Protein versus lactose',['protein','lactose','allerg']],['Microbial transfer',['board','micro','raw','salad']],['Matched controls',['separat','clean','ingredient','contact']]]],[['Why may lactose-free milk be unsafe for milk allergy?',['It can retain milk proteins','Lactose-free processing necessarily concentrates milk fat','Milk allergy is caused only by trace residual lactose','The absence of lactose prevents every digestive and immune reaction'],'Removing milk sugar does not necessarily remove allergenic proteins.'],['What does refrigeration do?',['Slows growth of many microorganisms','Sterilizes all food','Destroys every toxin','Guarantees unlimited storage'],'Cold storage reduces growth but is not sterilization.'],['Which is a reliable way to assess cooking temperature?',['Use an appropriate food thermometer','Use surface browning as proof of the center temperature','Rely on the same cooking time for every food thickness','Assume visible steam proves the required internal temperature'],'Internal temperature must be measured appropriately.'],['Which mechanism is central to lactose intolerance?',['Impaired digestion of lactose','An immune response to every milk protein','An immune-mediated injury triggered by gluten','Reduced pancreatic lipase activity affecting fat digestion'],'Reduced lactase activity can leave lactose undigested.']],{t:'w',kind:'sort',title:'Distinguish the hazard',buckets:['Allergen cross-contact','Microbial cross-contamination','Digestive intolerance'],items:[['Peanut residue on a shared utensil',0],['Milk protein in a lactose-free product for a milk-allergic person',0],['Raw poultry juices on salad',1],['Unwashed hands transferring organisms',1],['Undigested lactose fermented in the intestine',2],['Low lactase activity after milk intake',2]]},['FoodSafety.gov: food safety basics','https://www.foodsafety.gov/keep-food-safe/4-steps-to-food-safety']);

add('Medical nutrition therapy for diabetes and cardiovascular disease','Two meals contain the same calories but differ in carbohydrate distribution, fiber, sodium, and fat quality. Medical nutrition reasoning considers the variables relevant to the condition and the person, not just a calorie total.',[
 ['Glucose regulation links food and treatment','After a meal, digestible carbohydrate contributes to absorbed glucose and other sugars. Insulin helps coordinate glucose use and storage, while other hormones maintain availability between meals. Diabetes involves impaired glucose regulation through different mechanisms, so nutrition planning must fit the type, medications, activity, and goals. Carbohydrate amount and distribution can affect post-meal glucose, but food context also matters. Fiber, processing, meal composition, and portion influence responses. Fruit and legumes contain carbohydrate but also useful nutrients; avoiding every carbohydrate-containing food is not a complete diabetes plan. A person using medication that can lower glucose may face risk when meals are skipped. The appropriate response requires the care plan rather than a universal instruction to eat less.'],
 ['Use labels and meal patterns thoughtfully','Total carbohydrate per actual portion is often more informative than a front-label claim such as no added sugar. A product without added sugar can still contain carbohydrate, and a sugar-free product is not automatically nutritionally superior. Fiber and serving size should be read alongside total carbohydrate. Compare similar portions and consider the whole meal. A teaching example can show how doubling a serving doubles its stated carbohydrate, but it cannot predict an individual’s exact glucose rise. Timing of medication, illness, sleep, activity, and baseline physiology also matter. An individualized eating pattern should be sustainable, culturally acceptable, and accessible. Food records and glucose patterns can support discussion with the clinical team without turning every isolated result into a judgment about effort.'],
 ['Cardiovascular patterns involve substitutions','Dietary patterns relevant to cardiovascular health often emphasize fiber-rich plant foods, appropriate fat quality, and attention to sodium. Replacing some saturated fat with unsaturated fat differs from replacing it with refined carbohydrate or simply adding more food. A replacement changes two parts of the diet at once, so the alternative matters. Soluble or viscous fibers can influence cholesterol handling, while overall energy balance and other behaviors also contribute to risk. Sodium can affect blood-pressure management, but requirements and restrictions depend on the person and clinical plan. A low-fat product may contain substantial sodium or added sugar. No single label phrase summarizes cardiovascular suitability. Compare the actual composition and the role the food plays in the person’s pattern.'],
 ['Hypertension, heart failure, and fluid context','Blood pressure and fluid balance interact, but hypertension and heart failure are not identical conditions. Some people with heart failure require specific sodium or fluid guidance; others have different needs based on symptoms, treatment, kidney function, and laboratory values. A generic instruction to drink more water or restrict every fluid can therefore be inappropriate. Weight trends, swelling, breathlessness, intake, and medication changes may be relevant to clinical monitoring. Nutrition education should explain the purpose of a prescribed plan and how to follow it, while uncertainty or worsening symptoms should be communicated to the care team. Do not infer a personalized restriction from the disease name alone. The event’s medical nutrition domain asks for understanding of these relationships, not independent prescribing.'],
 ['Combine conditions without losing feasibility','A person with diabetes and hypertension may need to consider carbohydrate distribution, sodium, fiber, and medication timing simultaneously. Start by identifying the most important problem and the practical barriers. If meals are skipped because of work, a complex home-cooking plan may be less useful than a feasible meal option. If the person prefers a traditional dish, compare ways to adjust portions or ingredients while preserving its identity. Evaluate outcomes over time: intake consistency, relevant laboratory or home-monitoring trends, symptoms, and quality of life. A plan that is theoretically ideal but impossible to follow is unlikely to help. Shared decisions and professional follow-up connect nutritional mechanisms with daily life and prevent restrictive advice from undermining adequate intake.']
],[['Carbohydrate distribution','How carbohydrate is spread across meals and snacks. It interacts with medication timing and activity rather than functioning as an isolated rule.'],['Total carbohydrate','The label measure that includes several carbohydrate components. A no-added-sugar claim does not mean this quantity is zero.'],['Fat replacement','Changing one fat source or food for another. The health implication depends on what replaces saturated fat, not just on removing it.'],['Sodium context','The relationship between intake, blood pressure, fluid balance, and the individual clinical plan. A universal restriction is not appropriate for every circumstance.'],['Dietary pattern','The overall combination and frequency of foods over time. It is more informative than assigning a health value to one isolated ingredient.'],['Medication timing','The schedule and action of glucose-lowering treatment relative to intake and activity. Skipped meals can have different implications with different therapies.'],['Shared decision','A plan developed with the person that addresses clinical goals, preferences, and resources. It supports feasibility rather than assuming one menu fits everyone.'],['Monitoring trend','Repeated observations that help evaluate a plan. One glucose reading, weight, or meal does not fully describe long-term response.']],['A person with diabetes and hypertension chooses a snack labeled low fat and eats twice the listed serving. Explain how to evaluate it more carefully without prescribing a personal diet.',['Double the listed nutrient amounts to reflect the actual portion.','Review total carbohydrate, fiber, sodium, and the broader meal pattern rather than relying on low fat.','Consider medication timing, preferences, access, and the person’s established clinical plan.'],'The label claim describes only one characteristic. A useful comparison relates the actual portion and nutrient composition to the person’s goals and circumstances.',[['Actual portion',['double','serving','portion']],['Relevant nutrients',['carbohydrate','fiber','sodium']],['Clinical context',['medication','plan','context','preference']]]],[['A no-added-sugar product necessarily has what?',['No guarantee of zero total carbohydrate','Zero carbohydrate','Zero calories','No effect on any glucose response'],'Naturally occurring carbohydrate and other ingredients may remain.'],['Why does the replacement for saturated fat matter?',['Different replacement nutrients have different effects','All replacements are identical','Any reduction in fat has the same effect regardless of the replacement','Replacing saturated fat with refined carbohydrate is always equivalent to replacing it with unsaturated fat'],'Replacing saturated fat with unsaturated fat differs from replacing it with refined carbohydrate.'],['Which factor can make skipped meals relevant to glucose safety?',['The action of prescribed glucose-lowering medication','The assumption that fasting always prevents hypoglycemia','The belief that medication effects stop when a meal is skipped','The idea that total weekly carbohydrate alone determines short-term safety'],'Medication action must be considered alongside intake.'],['Which is the best basis for evaluating a dietary plan?',['Relevant trends and feasibility over time','One day of intake without checking usual patterns','A front-label claim without checking composition','The lowest energy total regardless of adequacy'],'Sustainable patterns and meaningful outcomes matter.']],{t:'w',kind:'sort',title:'Choose the variable being evaluated',buckets:['Carbohydrate or glucose reasoning','Cardiovascular composition','Feasibility and follow-up'],items:[['Total carbohydrate in the actual portion',0],['Meal timing relative to medication',0],['Replacing saturated with unsaturated fat',1],['Sodium in comparable portions',1],['Work schedule and food access',2],['Repeated outcomes and symptoms',2]]},['NIDDK: healthy living with diabetes','https://www.niddk.nih.gov/health-information/diabetes/overview/healthy-living-with-diabetes']);

add('Renal and gastrointestinal nutrition: adapt to the mechanism','A renal diet is not one fixed list of forbidden foods. Kidney disease stage, dialysis, laboratory values, appetite, and other conditions can change the appropriate nutritional priorities.',[
 ['Kidney function determines the problem','Kidneys regulate fluid, electrolytes, acid-base balance, and excretion of metabolic waste. Chronic kidney disease can alter these functions to different degrees. Potassium, phosphorus, sodium, fluid, and protein may require attention, but the relevant targets depend on stage, laboratory results, medications, and treatment. A person on dialysis can have different protein needs from a person with nondialysis disease. Applying one restriction to every renal patient can cause inadequate intake or miss the actual concern. A high potassium result must be interpreted clinically; it does not justify a student designing a treatment from a food list. The educational task is to connect impaired handling with the need for individualized assessment and monitoring.'],
 ['Read food information in renal context','Phosphorus occurs naturally in foods and can also appear in additives, with differences in absorption. Potassium content can vary with portion and preparation. Sodium often appears in processed or prepared foods but should be evaluated through actual composition rather than taste alone. A product marketed as a salt substitute may contain potassium and therefore needs review in relevant renal contexts. Protein supplies essential amino acids, but its metabolism also generates nitrogenous waste. These competing considerations explain why a renal plan may balance adequacy with metabolic management. Avoid reducing the issue to whether a food is healthy in general. The same food may fit one person’s plan and require adjustment in another’s, depending on the clinical situation.'],
 ['Gastrointestinal disease changes intake and absorption','Nutrition problems in gastrointestinal disease can arise from poor intake, impaired digestion, malabsorption, increased losses, or inflammation. Reflux affects the relationship between stomach contents and esophagus; individual triggers and treatment vary. Celiac disease can injure the small-intestinal surface and impair absorption. Inflammatory bowel disease can involve inflammation, symptoms, and nutrient loss, whereas irritable bowel syndrome does not imply the same destructive inflammatory process. Pancreatic insufficiency can impair enzyme delivery and fat digestion. A person with short bowel may have reduced absorptive capacity depending on which segments remain. These mechanisms lead to different needs. Naming the disease is the beginning of reasoning, not the end. Ask which function is disrupted and what evidence demonstrates the nutritional consequence.'],
 ['Symptoms and texture require specific assessment','Diarrhea can produce fluid and electrolyte losses, while constipation may relate to intake, activity, medications, or disease. Fiber is not one uniform treatment: different types and clinical circumstances matter. A person with an obstruction concern should not simply be told to add more bulk. Nausea, early satiety, pain, and swallowing difficulty can all limit intake through different mechanisms. Dysphagia concerns swallowing and may require a specialist assessment and prescribed texture or liquid consistency. Chewing difficulty from dentures is not the same problem. A texture change must support safe intake without unnecessarily reducing variety or nutrition. Clinical recommendations should be individualized, and persistent or severe symptoms require appropriate evaluation rather than trial-and-error restriction alone.'],
 ['Balance restriction against malnutrition risk','When several conditions overlap, restrictions can accumulate until little food remains acceptable. A person with kidney disease and gastrointestinal symptoms may reduce protein, fruit, dairy, and other foods without an organized plan. The result can be inadequate energy and nutrients even if each restriction began with a plausible concern. Assess intake, weight and function trends, symptoms, laboratory values, and the person’s priorities. A dietitian can help reconcile competing needs and identify acceptable alternatives. Follow-up tests whether the plan improves both the disease-related concern and nutritional adequacy. This is why medical nutrition therapy involves assessment, diagnosis of the nutrition problem, intervention, and monitoring rather than handing every person the same prohibited-food list.']
],[['Renal stage','The degree and pattern of kidney dysfunction, which helps determine nutritional concerns. It must be considered alongside treatment and laboratory findings.'],['Dialysis context','Treatment that changes removal of wastes and nutrients and can alter dietary needs. A nondialysis plan cannot automatically be transferred unchanged.'],['Phosphorus additive','A phosphorus-containing ingredient in a food product. Its presence and absorption can matter in renal planning, beyond the food’s general reputation.'],['Malabsorption','Impaired intestinal uptake of nutrients. It differs from inadequate intake and can occur despite eating apparently sufficient food.'],['Pancreatic insufficiency','Inadequate digestive enzyme delivery or activity in the relevant context. It can impair digestion, particularly fat handling, and requires clinical evaluation.'],['Dysphagia','Difficulty swallowing. It is distinct from chewing discomfort and may affect safe food and liquid consistency.'],['Competing restrictions','Multiple dietary limits that may conflict or reduce adequacy. They require prioritization and individualized review rather than automatic accumulation.'],['Nutrition monitoring','Follow-up of intake, symptoms, function, weight, and relevant laboratory findings to evaluate whether an intervention is both effective and adequate.']],['A person with kidney disease and chronic diarrhea has independently removed most protein foods, fruit, and dairy. Explain the risks of this approach and the information needed for a safer plan.',['Kidney stage, dialysis status, laboratory findings, and medications determine which renal modifications are relevant.','Diarrhea can add fluid, electrolyte, and nutrient losses and may indicate impaired absorption.','Multiple broad restrictions can reduce energy and nutrient adequacy, so intake and functional trends need assessment.'],'An individualized professional plan should address the actual mechanisms while preserving adequate, acceptable food. A generic renal label is insufficient to choose all restrictions.',[['Renal context',['stage','dialysis','laboratory']],['Digestive losses',['diarrhea','loss','absorp']],['Adequacy and individualization',['adequate','restrict','individual','dietitian']]]],[['Why do protein recommendations differ across renal contexts?',['Disease stage and dialysis alter needs and handling','Protein is never needed in kidney disease','Every patient has identical losses','Only age determines the plan'],'Renal treatment and function change the balance between adequacy and metabolic concerns.'],['Which product may need review because it contains potassium?',['Some salt substitutes','Plain water in every case','All foods labeled low fat by definition','Every food without sodium'],'Some substitutes replace sodium chloride with potassium salts.'],['Which condition directly concerns swallowing?',['Dysphagia','Lactose intolerance','Hyperlipidemia','Glycosuria'],'Dysphagia can affect safe texture and liquid choices.'],['What is a risk of accumulating many restrictions?',['Inadequate energy and nutrient intake','Guaranteed correction of every disease','Automatic improvement in absorption','Elimination of monitoring needs'],'Restrictions can undermine adequacy if not coordinated.']],{t:'w',kind:'sort',title:'Identify the disrupted step',buckets:['Intake barrier','Digestion or absorption','Excretion or regulation'],items:[['Painful chewing limits meals',0],['Nausea reduces appetite',0],['Insufficient pancreatic enzymes',1],['Damaged intestinal surface',1],['Reduced renal potassium handling',2],['Impaired kidney fluid regulation',2]]},['NIDDK: eating right for chronic kidney disease','https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/eating-nutrition']);

add('Cancer, special needs, and integrated nutrition assessment','A person losing weight during treatment may need help with mouth pain, nausea, fatigue, or swallowing rather than another list of foods to avoid. Nutrition care begins with the mechanism limiting intake and the person’s goals.',[
 ['Cancer and treatment affect nutrition through many routes','Cancer can alter metabolism and increase inflammatory burden, while treatment can affect appetite, taste, smell, mouth comfort, swallowing, and gastrointestinal function. Weight loss may reflect reduced intake, metabolic change, fluid shifts, or several factors. Cachexia is a complex syndrome involving loss of muscle and other changes and is not simply ordinary starvation that always resolves with more calories. This distinction does not make nutrition support irrelevant; it explains why symptom management and medical care must accompany nutritional assessment. Avoid promises that a particular food can cure cancer or that all patients should eliminate a broad nutrient class. The appropriate plan depends on disease, treatment, symptoms, nutritional status, and the person’s priorities.'],
 ['Identify the barrier before adapting the meal','Mouth sores may make acidic, rough, or very hot foods uncomfortable, while taste changes can alter what is acceptable. Early satiety means feeling full quickly and can reduce total intake. Nausea may vary with treatment timing, odors, or other factors. Fatigue can limit shopping, cooking, and eating effort. Each barrier suggests a different assessment question. Smaller portions offered more often may be considered in some plans, while texture, temperature, and food choice can be adapted to comfort and swallowing safety. These are possibilities to discuss, not universal prescriptions. A person’s favorite food may become aversive during treatment, and forcing it can worsen distress. The goal is to support feasible intake while the care team addresses the underlying symptoms.'],
 ['Special needs require access and function assessment','Disability, neurological disease, sensory differences, or cognitive impairment can affect obtaining, preparing, or eating food. Adaptive utensils, positioning, assistance, accessible packaging, and predictable routines may help when matched to the actual need. A person who needs physical assistance should still be involved in preferences and decisions as much as possible. Swallowing safety requires appropriate assessment; changing texture casually can fail to address the problem or reduce intake. Communication differences should not be mistaken for lack of understanding. Ask how the person normally communicates hunger, discomfort, and preferences. Caregiver knowledge is valuable, but the person’s autonomy remains important. Nutrition support should be integrated with occupational, speech-language, nursing, medical, and dietetic care where relevant.'],
 ['Routes of nutrition support have different indications','Oral intake is used when safe and sufficient. Enteral nutrition delivers nutrients through the gastrointestinal tract using a tube when appropriate. Parenteral nutrition delivers nutrients intravenously when the gastrointestinal route cannot adequately be used in the relevant clinical situation. These routes are not ranked simply by how advanced they sound. Gut function, swallowing safety, expected duration, risks, goals, and the person’s condition influence selection. Enteral feeding does not eliminate every aspiration risk, and parenteral nutrition requires careful monitoring of metabolic and catheter-related concerns. A classroom lesson should identify the route and rationale without providing a formula prescription. Clinical teams determine composition, rate, and monitoring using current standards and the individual assessment.'],
 ['Use the nutrition care process','Assessment gathers intake, symptoms, medical history, medications, physical and functional findings, relevant measurements, and social context. A nutrition diagnosis describes the nutrition problem and its contributing factors, which is not identical to the medical diagnosis. Intervention addresses the identified problem, and monitoring evaluates response. For example, a medical diagnosis of cancer does not specify whether the immediate nutrition problem is painful swallowing, inadequate food access, or altered absorption. A clear case explanation links cause, evidence, action, and follow-up. Outcomes can include improved intake, symptom relief, function, and quality of life, not only body weight. Respect the person’s goals, including comfort-focused goals when relevant. Good reasoning is specific enough to be useful and cautious enough not to invent unsupported treatment details.']
],[['Early satiety','Feeling full after a small amount of food. It can reduce intake and should be investigated in context rather than interpreted as a lack of effort.'],['Cachexia','A complex illness-associated syndrome involving muscle loss and metabolic changes. It is not always reversible by calories alone and requires coordinated care.'],['Mucositis','Inflammation or injury of mucosal tissues that can make eating painful. Its effects depend on location, severity, and treatment context.'],['Adaptive support','Tools or assistance matched to a functional barrier, such as utensils or positioning. Support should preserve autonomy and preferences where possible.'],['Enteral nutrition','Delivery of nutrients through the gastrointestinal tract, often by tube when oral intake is insufficient or unsafe and the gut can be used appropriately.'],['Parenteral nutrition','Intravenous delivery of nutrients when indicated. It requires specialized assessment and monitoring and is not simply a superior version of ordinary feeding.'],['Nutrition diagnosis','A description of a nutrition problem and its contributing factors. It differs from the medical disease label and guides the nutrition intervention.'],['Goal-concordant care','Care aligned with the person’s priorities and clinical situation, including function, comfort, and quality of life as well as nutritional measures.']],['A person receiving cancer treatment has mouth pain, early satiety, fatigue, and declining intake. Explain how a nutrition assessment should connect these barriers to possible supports and follow-up without promising a cure or prescribing a formula.',['Assess symptoms, swallowing safety, intake, weight and function trends, treatment effects, access, and goals.','Mouth comfort, manageable portions, practical meal assistance, and clinical symptom treatment may address different barriers.','If oral intake remains inadequate, the team evaluates appropriate support routes based on gut function, safety, and goals.'],'Monitor intake, symptoms, function, and quality of life. Nutritional support complements cancer care and should be individualized rather than presented as a disease cure.',[['Identifies barriers',['mouth','satiety','fatigue','symptom']],['Connects support to mechanism',['comfort','portion','assist','swallow']],['Monitoring and goals',['monitor','function','quality','goal']]]],[['What distinguishes enteral from parenteral nutrition?',['Enteral uses the gastrointestinal tract; parenteral is intravenous','Both always use a peripheral vein','Enteral means only ordinary chewing','Parenteral always means a stomach tube'],'The route distinguishes the terms.'],['Why is cachexia not simply equivalent to low food intake?',['Metabolic and inflammatory changes contribute','Food intake is never relevant','It always resolves after one meal','It occurs only in healthy people'],'Cachexia can involve mechanisms beyond insufficient calories alone.'],['Which response best addresses fatigue limiting food preparation?',['Assess practical meal assistance and accessible options','Provide a recipe plan that requires more preparation time','Focus only on nutrient information without practical help','Assume a supplement recommendation removes the need to assess function'],'Functional barriers need feasible supports.'],['Which outcome can be relevant beyond weight?',['Function and quality of life','Only body weight without considering fluid shifts','Only prescribed calories without assessing intake','Only the number of supplement products used'],'Nutrition care evaluates outcomes aligned with the person’s situation and goals.']],{t:'w',kind:'order',title:'Apply the nutrition care process',steps:['Gather intake, symptoms, function, and clinical context','Identify the nutrition problem and contributing factors','Choose an individualized intervention with the person and team','Implement the agreed support','Monitor relevant outcomes','Reassess and adapt the plan']},['National Cancer Institute: nutrition in cancer care','https://www.cancer.gov/about-cancer/treatment/side-effects/appetite-loss/nutrition-pdq']);

add('Minerals, water, and electrolyte balance','A person can lose water and salts together, or retain water while diluting a blood electrolyte. Fluid balance is therefore more complicated than labeling every problem dehydration.',[
 ['Minerals are elements with distinct jobs','Minerals are inorganic elements required for structure and regulation. Calcium contributes to bone, muscle contraction, signaling, and coagulation. Phosphorus supports bone and energy-related molecules. Magnesium participates in numerous enzyme functions. Iron is important in oxygen transport and other processes; zinc supports enzyme activity, growth, and wound healing; iodine supports thyroid hormone synthesis. Trace minerals are needed in smaller quantities than major minerals, but smaller does not mean unimportant. Mineral content and absorption are separate issues. Food composition, chemical form, other nutrients, intestinal health, and physiological need can influence bioavailability. A person’s fatigue does not establish iron deficiency, and a single supplement should not be selected without considering alternative causes and relevant assessment.'],
 ['Fluid compartments and osmosis','Body water occupies intracellular and extracellular compartments. Extracellular fluid includes interstitial fluid and plasma. Sodium is a major extracellular cation; potassium is a major intracellular cation. Osmosis describes movement of water across a selectively permeable membrane in response to effective solute differences. Water distribution is therefore influenced by both total water and solute content. Edema is excess interstitial fluid, but a person with edema may still have an ineffective circulating volume in some illnesses. Dehydration, low blood volume, and low sodium are not synonyms. A water deficit can concentrate sodium, while excess water relative to sodium can dilute it. The direction of a laboratory value must be interpreted alongside the clinical context rather than guessed from thirst alone.'],
 ['Regulation involves several systems','Thirst supports intake, and kidneys adjust excretion. Antidiuretic hormone promotes water conservation through renal effects, while aldosterone contributes to sodium handling and potassium excretion. Circulatory signals and other hormones also participate. Water enters through beverages, foods, and metabolic processes; it leaves through urine, skin, lungs, and stool. Needs and losses vary with temperature, activity, age, illness, medications, and kidney function. A fixed fluid target is therefore not appropriate for every person. High losses through diarrhea can remove water and electrolytes together. Replacing only one component may not correct the full disturbance. Severe symptoms or major electrolyte abnormalities require clinical management; a classroom model should teach mechanisms without serving as a treatment calculator.'],
 ['Assess trends rather than one isolated observation','Fluid assessment may include intake and output, body-weight trends, urine findings, examination, symptoms, and laboratory values. Rapid weight change over a short interval often reflects fluid shifts more than changes in fat or muscle. Dark urine can suggest concentration but is not a complete hydration test and can have other causes. Reduced urine output can reflect several mechanisms, including poor perfusion or kidney dysfunction. Potassium abnormalities can affect cardiac conduction; sodium abnormalities can affect neurological function. Those relationships explain why symptoms and context matter. A recorded intake must include relevant fluids from food, medications, and nutrition support according to the setting. An apparently precise number is still misleading if important sources or losses were omitted.'],
 ['Mineral interactions and practical interpretation','Calcium and vitamin D interact in bone physiology, while vitamin C can enhance nonheme iron absorption. Phytate and other food components can affect mineral availability, but this does not make all plant foods nutritionally inadequate. Evaluate the whole diet. Excess mineral supplementation may interfere with other nutrients or cause toxicity, especially when excretion is impaired. In renal disease, potassium or phosphorus management depends on laboratory values, stage, and treatment. A person should not universally remove every food containing those minerals based on a disease label. The most useful study pattern is function, food source, absorption factors, deficiency implications, and excess concerns. This organizes information without turning one nutrient into a cure-all or a universal hazard.']
],[['Electrolyte','A dissolved substance that contributes charged particles. Electrolytes support fluid distribution, electrical signaling, and other functions; they are not interchangeable with water.'],['Sodium','A major extracellular cation involved in fluid balance and electrical activity. Blood concentration reflects water relationships as well as sodium content.'],['Potassium','A major intracellular cation important for nerve and muscle function. Abnormal levels can affect cardiac conduction and require contextual clinical interpretation.'],['Osmosis','Movement of water across a selectively permeable membrane in response to effective solute differences. It helps explain why concentration changes alter cellular water.'],['Edema','Excess fluid in interstitial tissues. It is not proof that all fluid compartments are adequately supplied or that the person simply drank too much water.'],['Bioavailability','The fraction of an ingested nutrient available for absorption and use. Food content alone does not determine how much the body obtains.'],['Iron','A mineral important for hemoglobin and other functions. Deficiency is one possible cause of anemia, but anemia and fatigue have other causes too.'],['Fluid trend','A pattern across intake, output, weight, symptoms, and measurements. It is usually more informative than one isolated observation or a universal intake rule.']],['A person has repeated diarrhea, falling weight over two days, and reduced urine output. Explain why both water and electrolytes matter and why a single fixed drinking target is insufficient.',['Diarrhea removes fluid and dissolved electrolytes, and the weight trend may reflect fluid loss.','Reduced output may indicate a conservation response or a more concerning physiological problem.','Age, losses, kidney function, symptoms, and laboratory findings determine the appropriate clinical response.'],'The case calls for assessment of volume and solute balance together. It does not justify choosing a personalized replacement regimen from thirst or weight alone.',[['Fluid loss',['diarrhea','weight','fluid']],['Electrolyte role',['sodium','potassium','electrolyte']],['Individual assessment',['kidney','symptom','assess','laboratory']]]],[['Which ion is predominantly intracellular?',['Potassium','Sodium','Chloride','Calcium in plasma'],'Potassium is the principal intracellular cation.'],['A rapid weight change over one day most directly suggests what to assess?',['Fluid shifts','A large change in fat tissue alone','New muscle growth alone','A stable change in long-term energy stores'],'Short-term weight changes often reflect water balance.'],['Which mineral supports thyroid hormone synthesis?',['Iodine','Iron','Calcium','Sodium'],'Iodine is a component of thyroid hormones.'],['Why can food mineral content differ from absorbed amount?',['Bioavailability varies with form and context','All minerals are absorbed completely','The listed mineral amount always equals the absorbed amount','A higher labeled dose always produces proportionally higher absorption'],'Absorption depends on multiple dietary and physiological factors.']],{t:'w',kind:'sort',title:'Separate nutrient roles from assessment data',buckets:['Nutrient or electrolyte role','Assessment observation'],items:[['Iron supports hemoglobin',0],['Potassium supports electrical activity',0],['Iodine supports thyroid hormone',0],['Calcium supports bone structure',0],['Rapid weight change',1],['Recorded urine output',1],['Intake record',1],['Blood electrolyte result',1]]},['NIH ODS: Iron fact sheet','https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/']);

add('Nutrition during pregnancy, infancy, childhood, and adolescence','Growth changes nutrient needs, but development also changes feeding skills and independence. Nutrition planning must consider both physiology and what a person can safely and realistically eat.',[
 ['Pregnancy and preparation for development','Pregnancy changes demands for energy and several nutrients, including folate, iron, iodine, and others. Folate’s role in DNA synthesis helps explain its importance before conception and in early development. Iron supports expanded maternal blood volume and fetal needs. These mechanisms do not imply that all nutrients should be doubled or that eating for two means twice the food. Requirements depend on the stage and the person’s situation. Nausea, vomiting, food access, dietary restrictions, and medical conditions can affect intake. Food safety also matters because some infections pose greater risks during pregnancy. Individual supplement decisions and clinical targets belong with qualified care. A study case should identify the physiological need and the information required rather than invent a regimen from a general rule.'],
 ['Infant feeding is developmentally specific','Infants have rapid growth and small stomach capacity. Human milk or appropriate infant formula supplies nutrition during early life according to the feeding plan. Formula preparation must follow the manufacturer’s and clinician’s instructions; changing concentration can disturb nutrient and fluid balance. Complementary foods are introduced when developmentally appropriate, alongside continued milk feeding under current guidance. Readiness involves more than chronological age, including head control and ability to manage food safely. Texture and shape affect choking risk. Feeding is a responsive interaction: adults provide safe, appropriate food and attend to hunger and fullness signals. A crying infant does not always need more food, and forcing intake can undermine the interaction. Growth is assessed through trends and clinical context, not one isolated measurement.'],
 ['Childhood patterns and food learning','Children need nutrient-rich food in portions suited to development and appetite. Repeated neutral exposure can help familiarity with new foods. Pressure, punishment, or labeling foods as morally good and bad can complicate eating. Family meals can support learning, but schedules, culture, resources, and caregiver stress affect what is feasible. Iron, calcium, vitamin D, protein, and other nutrients support growth, yet no single food is mandatory if alternatives meet needs. Food allergies, sensory differences, dental problems, and swallowing difficulties require individualized consideration. Distinguish normal variation in appetite from a persistent problem affecting growth or function. A child’s size alone does not reveal dietary adequacy, and changes should be evaluated with an appropriate growth reference and medical history.'],
 ['Adolescence combines growth and autonomy','Adolescents experience changes in body composition, skeletal development, and energy needs. Menstruation can affect iron requirements, while bone development makes calcium and vitamin D relevant. Physical activity, sleep, school schedules, body image, and social influences shape eating. Sports participation does not automatically justify supplements or extreme protein intake. Marketing claims can appeal to performance or appearance without providing strong evidence. Adolescents may begin vegetarian or other dietary patterns for ethical, cultural, or personal reasons; a well-planned pattern should address nutrients such as B12 where relevant. Restrictive eating, persistent fatigue, or changes in function deserve attention without shame. Nutrition education should build skills in evaluating labels, planning accessible meals, and identifying reliable support rather than focusing solely on weight.'],
 ['Assess the whole developmental context','A useful lifespan assessment asks about growth trend, feeding skills, appetite, gastrointestinal symptoms, food availability, cultural practices, medications, and relevant health conditions. For a young child with poor intake, ask whether chewing pain, texture difficulty, meal timing, or access is the barrier. For an adolescent who skips breakfast, ask about time, appetite, transport, and school food options rather than assuming lack of motivation. A plan is more likely to work when it addresses the actual barrier. Nutrient requirements are reference tools, not a reason to ignore the person. The HOSA lifespan domain rewards understanding how changing physiology interacts with practical feeding conditions. Explain those links clearly before considering what further assessment or professional input is needed.']
],[['Developmental readiness','The motor and oral skills needed to manage a feeding task safely. Chronological age alone does not capture every aspect of readiness.'],['Responsive feeding','A feeding interaction that attends to hunger, fullness, and developmental cues while providing safe and appropriate food opportunities. It differs from pressure or force.'],['Growth trend','Change across repeated measurements interpreted with an appropriate reference and clinical context. One value alone cannot establish the cause of a nutrition concern.'],['Folate','A nutrient supporting DNA synthesis, particularly important during periods of rapid cell division. Its developmental role does not justify unlimited supplementation.'],['Iron demand','The need for iron related to blood-cell production, growth, and losses. Life stage and individual factors influence the relevant requirement.'],['Complementary foods','Foods introduced alongside milk feeding when developmentally appropriate. Their texture, nutrient content, and safety must match the infant’s abilities and needs.'],['Adolescent autonomy','Increasing control over food choices, shaped by peers, schedules, access, and values. Education should develop decision skills rather than assume noncompliance.'],['Feeding barrier','A factor such as pain, texture difficulty, access, or timing that limits intake. Identifying the barrier guides a more useful response than a generic instruction to eat more.']],['An adolescent avoids animal products, skips meals because of an early bus, and feels tired. Explain what should be assessed without assuming a single deficiency.',['Review the full food pattern, meal access, growth, activity, sleep, symptoms, and relevant health history.','A plant-based pattern needs a reliable B12 source and attention to nutrients such as iron, but tiredness alone proves neither deficiency.','An accessible meal option that fits the bus schedule addresses a practical barrier.'],'The assessment should respect the person’s values while identifying nutritional and nonnutritional contributors. A diagnosis or supplement regimen requires appropriate professional evaluation.',[['Pattern and nutrients',['b12','iron','pattern']],['Practical access',['bus','schedule','access']],['Avoids single-cause assumption',['sleep','assess','not','cause']]]],[['Why is folate important in early development?',['It supports DNA synthesis and cell division','It supplies 9 kcal/g','It replaces all protein needs','It prevents every developmental disorder'],'Folate supports processes required in rapidly dividing cells.'],['What is essential when preparing infant formula?',['Follow the specified concentration instructions','Dilute it freely to save money','Double the powder for faster growth','Use any household ratio'],'Changing concentration can alter nutrient and fluid balance.'],['Which approach best supports food learning in children?',['Repeated neutral exposure without pressure','Punishment for refusing a food','Forcing completion of every plate','Treating every appetite change as disease'],'Neutral exposure supports familiarity while respecting feeding cues.'],['What is more informative than one growth measurement?',['A trend interpreted in context','A peer’s body size','A package claim','One day’s appetite alone'],'Growth patterns need repeated measurement and clinical interpretation.']],{t:'w',kind:'sort',title:'Match the concern to its main developmental context',buckets:['Pregnancy','Infancy','Adolescence'],items:[['Expanded maternal blood volume',0],['Early fetal cell division',0],['Safe formula concentration',1],['Readiness for complementary textures',1],['Increasing independent food choices',2],['School schedules and sports marketing',2]]});

add('Adult nutrition, aging, culture, and food access','A person may understand nutrition advice perfectly yet lack transport, money, cooking equipment, or comfortable dentures. A useful plan starts by finding the real barrier.',[
 ['Adult needs change with circumstances','Adult energy requirements vary with body size, activity, health, and physiological state. Nutrient adequacy depends on the eating pattern over time, not one ideal meal. Work schedules, caregiving, travel, and finances shape what people can obtain and prepare. Shift work can disrupt meal timing and sleep, while physically demanding activity can alter fuel and fluid needs. A sustainable plan fits these conditions rather than assuming unlimited time for food preparation. Nutrition assessment should distinguish what is eaten, what is available, and what is preferred. A record of skipped meals does not explain whether the cause is low appetite, lack of opportunity, nausea, cost, or intentional restriction. Each explanation suggests a different kind of support.'],
 ['Aging and nutrient density','Older adults may have lower energy needs while still requiring adequate protein, vitamins, minerals, and fluid. This increases the importance of nutrient density. Aging can coincide with changes in taste, smell, dentition, mobility, swallowing, gastrointestinal function, and social connection. Medications can affect appetite, dry mouth, taste, or nutrient handling. Sarcopenia involves loss of muscle mass and function in context; nutrition and physical activity are both relevant to maintaining function. A person’s age does not determine their abilities or preferences. Some older adults remain highly active, while others face substantial limitations. Avoid assuming that every older person needs the same texture, supplement, or restriction. Assess function and goals directly and use appropriate professional input for clinical concerns.'],
 ['Culture is part of the solution','Food practices can reflect religion, family, geography, identity, ethics, and personal preference. People within the same cultural group do not all eat alike. Ask what foods are meaningful and routinely available rather than relying on stereotypes. Familiar dishes can often be adapted to meet nutrition needs without discarding the whole pattern. The relevant question may concern portion, preparation, ingredient substitution, or meal frequency. A clinician’s preferred food is not automatically the only valid source of a nutrient. For example, calcium can come from several foods and fortified products, depending on availability and tolerance. Respectful communication explains the nutritional purpose of a change and invites the person to identify acceptable ways to achieve it.'],
 ['Food insecurity and structural constraints','Food insecurity concerns unreliable access to sufficient food. It can coexist with higher body weight, micronutrient deficiency, or chronic disease. Limited money can favor inexpensive energy-dense options, while lack of refrigeration can restrict perishables. Transportation, neighborhood retail options, disability, and work hours all affect access. A plan requiring daily shopping or specialized expensive ingredients may fail despite strong motivation. Screening should be respectful and connected to resources. Meal programs, community supports, transportation assistance, and benefits may address barriers beyond education. Do not equate an inaccessible plan with unwillingness. Distinguish an individual preference from a structural limitation and explain how that distinction changes the recommended support. The goal is feasible nourishment, not compliance with an idealized menu.'],
 ['Communication and evaluation','Use plain language, ask open questions, and check understanding through teach-back. Teach-back asks the person to explain the plan in their own words; it evaluates the clarity of communication rather than testing intelligence. Shared goals should be specific and realistic. For someone with chewing pain, a nutrition response might include assessment of oral health and acceptable softer foods, not merely a handout about vegetables. Follow-up examines whether the barrier improved, intake changed, and relevant outcomes moved in the intended direction. Body weight alone is not a complete outcome measure; function, symptoms, intake quality, and quality of life may matter. A respectful assessment can identify both clinical needs and practical opportunities without moral judgments about food or body size.']
],[['Nutrient density','Nutrients supplied relative to energy or food amount. It becomes especially relevant when energy needs or appetite decline but nutrient needs remain substantial.'],['Sarcopenia','Loss of muscle mass and function in the relevant clinical context. It cannot be assessed solely by appearance or corrected by one food claim.'],['Food insecurity','Unreliable access to sufficient food. It can occur at different body sizes and may involve economic, geographic, or functional barriers.'],['Cultural humility','An approach that asks about a person’s own practices and priorities instead of assuming that group identity predicts every food choice.'],['Teach-back','Asking someone to explain information in their own words to assess how clearly it was communicated. It is not an examination of intelligence.'],['Texture adaptation','Changing food consistency to address an identified need. Chewing difficulty and swallowing impairment are different concerns and require appropriate assessment.'],['Shared goal','A feasible objective developed with the person, reflecting nutritional needs and their priorities. It should account for resources and daily routines.'],['Structural barrier','An external constraint such as transport, cost, or refrigeration. Education alone may not remove it, so practical resources can be necessary.']],['An older adult with painful dentures and no reliable transportation skips meals. Propose an assessment framework that respects familiar foods and distinguishes education from access needs.',['Assess oral discomfort, chewing and swallowing, intake, hydration, weight and function trends, medications, and available help.','Ask which familiar foods are acceptable and whether softer nutrient-dense versions are feasible.','Address dental care and transport or meal resources rather than assuming the person simply needs more motivation.'],'The framework combines physiology, preference, and access. Follow-up should determine whether the practical barriers and nutritional consequences improve.',[['Clinical and functional assessment',['denture','chew','intake','function']],['Cultural preferences',['familiar','preference','acceptable']],['Access support',['transport','meal','resource']]]],[['Which statement about food insecurity is accurate?',['It can coexist with higher body weight','It occurs only with visible wasting','It means a person dislikes vegetables','It is solved by information alone'],'Food insecurity describes access, not a single body appearance.'],['What is the purpose of teach-back?',['Check clarity of communication','Confirm agreement without asking for an explanation','Measure memory without adapting the explanation','Replace later assessment of whether the plan is feasible'],'Teach-back reveals whether the explanation was understandable.'],['Which change directly addresses a transport barrier?',['A feasible meal-delivery or transport resource','A nutrition handout without an access resource','A detailed meal plan requiring more shopping trips','A fresh-food plan that assumes daily transport'],'Access problems require practical solutions.'],['Why may nutrient density matter more with reduced appetite?',['Less food must still provide adequate nutrients','Lower appetite reduces every nutrient requirement proportionally','Maintaining calorie intake alone guarantees adequacy','A multivitamin necessarily replaces protein and food energy'],'Reduced intake increases the importance of nutrient content in available portions.']],{t:'w',kind:'sort',title:'Identify the barrier before choosing support',buckets:['Physical or clinical','Access or environment','Preference or communication'],items:[['Painful dentures',0],['Difficulty swallowing',0],['No refrigerator',1],['No transport to shops',1],['Unfamiliar suggested foods',2],['Instructions not understood',2]]});

add('Macronutrients, food energy, and serving-size reasoning','Two snacks contain the same calories but different amounts of fiber, protein, and fat. Energy arithmetic answers one question; understanding nutritional quality requires several more.',[
 ['What macronutrients contribute','Carbohydrates, proteins, and fats are required in relatively large amounts and can supply energy. Digestible carbohydrate and protein each provide approximately 4 kilocalories per gram, while fat provides approximately 9. A food-label Calorie is a kilocalorie. Water and minerals do not provide energy, and vitamins help physiological processes without supplying calories themselves. Alcohol supplies energy but is not an essential nutrient. These facts explain why grams and calories cannot be used interchangeably. A gram measures mass, while a kilocalorie measures energy. A food with more fat may provide more energy per gram, but energy density is not identical to nutritional value. Compare what a food contributes within the whole eating pattern rather than classifying it solely by one macronutrient.'],
 ['Carbohydrate structure changes behavior','Monosaccharides include glucose, fructose, and galactose. Disaccharides join two sugar units: sucrose contains glucose and fructose, lactose glucose and galactose, and maltose two glucose units. Starch contains longer glucose chains. Glycogen is an animal storage form found principally in liver and muscle. Dietary fiber includes carbohydrate components that human digestive enzymes do not break down in the same way as starch. Some fiber is fermented by intestinal microbes; different fibers affect stool bulk, viscosity, and microbial metabolism differently. Simple and complex describe molecular structure, not a complete health ranking. A food’s processing, fiber, meal context, and portion influence its effects. Fruit contains sugars but also water, fiber, and micronutrients; reducing all carbohydrate-containing foods to sugar misses those differences.'],
 ['Protein and fat are more than fuel','Proteins supply amino acids for enzymes, transport proteins, immune molecules, muscle, and other tissues. Essential amino acids must come from food because the body cannot make enough of them. A varied pattern can combine plant sources to supply indispensable amino acids; every mouthful does not need an identical amino-acid profile. Fatty acids differ in chain length and saturation. Saturated fatty acids have no carbon-carbon double bonds, while unsaturated fatty acids have one or more. Essential fatty acids must be supplied through the diet. Fat supports cell membranes, signaling, and absorption of vitamins A, D, E, and K. Neither a high-protein label nor a low-fat label establishes that a product is the best choice for a particular person or purpose.'],
 ['Calculate energy with units and portions','For a teaching example containing 20 g carbohydrate, 8 g protein, and 6 g fat, multiply each by its energy factor: 80, 32, and 54 kcal respectively. The estimate is 166 kcal. If those values describe one serving and a person consumes two servings, the estimated energy is 332 kcal. Do not multiply by both serving number and package size unless the question requires both. A label’s listed calories may differ slightly from a simple calculation because of rounding, fiber accounting, and specific energy factors. Show units at each step and interpret the result as an estimate. A nutrient percentage requires the nutrient’s energy divided by total energy, not grams divided by total grams. Six grams of fat does not mean six percent of energy.'],
 ['Read labels without reducing food to a score','Begin with serving size and servings per container. Then inspect the nutrients relevant to the question, such as total carbohydrate, fiber, sodium, or saturated fat. Compare like portions. A larger serving can make a product appear more nutrient-rich simply because more food is represented. Nutrient density concerns nutrients relative to food amount or energy; energy density concerns calories per amount of food. A fortified product may provide selected vitamins yet still differ from another food in fiber or sodium. Personal needs also depend on age, activity, health, preferences, and access. The interactive energy model is a learning tool for the 4/4/9 relationship, not a prescription for calorie intake or a judgment of a person’s eating.']
],[['Energy density','The energy supplied per amount of food, commonly per gram. It differs from nutrient density, which asks about the nutrients supplied relative to amount or energy.'],['Carbohydrate','A nutrient class including sugars, starches, and fiber. Digestible carbohydrate supplies about 4 kcal/g, while fiber has different digestive and energy characteristics.'],['Protein','An amino-acid source used for structural and functional molecules as well as energy. More protein alone does not guarantee greater muscle growth.'],['Fat','A concentrated energy source supplying about 9 kcal/g. It also supports membranes and fat-soluble vitamin absorption, so its role is not merely calorie storage.'],['Essential nutrient','A substance the body cannot synthesize in sufficient amounts and therefore must obtain through the diet. Essential does not mean that a supplement is always needed.'],['Serving size','The amount represented by the label’s nutrient values. It must be distinguished from the amount actually eaten and the total amount in the package.'],['Fiber','Dietary components resistant to ordinary human digestive enzymes, with varied effects on bowel function, viscosity, and microbial fermentation. Different fibers are not functionally identical.'],['Nutrient density','The concentration of useful nutrients relative to energy or amount of food. It cannot be inferred from calories alone or from one marketing phrase.']],['A snack label lists 20 g carbohydrate, 8 g protein, and 6 g fat per serving. A package contains two servings. Estimate energy for the whole package and explain what this calculation cannot tell you.',['One serving supplies 20×4 + 8×4 + 6×9 = 166 kcal.','Two servings supply approximately 332 kcal.','This does not reveal fiber, micronutrients, sodium, fullness, or whether the food fits an individual’s overall needs.'],'The calculation is useful for interpreting the stated portion, but food quality and personal suitability require more information. Label rounding can also make the listed calorie total differ slightly.',[['Correct factors',['4','9','factor']],['Correct serving calculation',['166','332','two']],['Recognizes limitations',['fiber','micronutrient','sodium','context']]]],[['Which nutrient provides about 9 kcal per gram?',['Fat','Protein','Digestible carbohydrate','Water'],'Fat has a higher energy value per gram than carbohydrate or protein.'],['Lactose is classified as what?',['Disaccharide','Amino acid','Mineral','Fatty acid'],'Lactose contains glucose and galactose.'],['A food has 10 g fat and 200 kcal total. Approximately what percentage of its energy comes from fat?',['45%','5%','10%','90%'],'10×9 = 90 kcal; 90/200×100 = 45%.'],['What must be checked first when comparing two labels?',['Whether the serving amounts are comparable','Whether the calorie totals match even if portions differ','Whether both make the same front-label claim','Whether one protein number is higher without adjusting portions'],'Portion differences can distort every nutrient comparison.']],{t:'w',kind:'nutritionlab',title:'Explore food energy'});

add('Digestion, absorption, and metabolic pathways','Adequate food intake does not guarantee adequate nourishment. A person can eat enough yet fail to digest or absorb a nutrient. Following a meal through the body reveals where different failures can occur.',[
 ['Mechanical and chemical digestion','Mechanical digestion breaks food into smaller pieces and mixes it with secretions. Chewing and stomach mixing increase the surface available for enzymes. Chemical digestion breaks molecular bonds: amylases act on carbohydrate, proteases on protein, and lipases on fat. Digestion begins before the small intestine, but each region has specialized conditions. Salivary amylase begins starch digestion. Stomach acid helps unfold proteins and supports pepsin activity; acid itself is not a universal enzyme. The stomach also helps regulate delivery into the small intestine. The digestive tract is not simply a passive tube. Neural signals, hormones, motility, and secretions coordinate processing. A symptom such as abdominal discomfort can arise at many points, so location and timing matter when investigating a problem.'],
 ['The small intestine and accessory secretions','The pancreas releases digestive enzymes and bicarbonate into the small intestine. Bicarbonate helps neutralize acidic gastric contents, supporting conditions in which intestinal and pancreatic enzymes function. The liver produces bile, and the gallbladder stores and concentrates it between meals. Bile emulsifies fat into smaller droplets and helps form structures that support lipid absorption. It is not itself a digestive enzyme. Brush-border enzymes at the intestinal surface complete several digestion steps, including splitting certain disaccharides. Lactase splits lactose into absorbable sugars. When lactose remains undigested, it can retain water in the lumen and be fermented by microbes, producing gastrointestinal symptoms. This mechanism differs from an immune allergy to milk proteins. The same food can therefore create symptoms through very different pathways.'],
 ['Absorption routes and surface area','Villi and microvilli increase the absorptive surface of the small intestine. Nutrients cross intestinal cells through different transport mechanisms. Monosaccharides and amino acids generally enter portal blood, which carries them toward the liver. Many absorbed long-chain lipids are packaged into chylomicrons and enter lymphatic vessels before reaching the bloodstream. These routes explain why fat handling differs from carbohydrate handling. Vitamin B12 absorption depends on a specialized pathway involving intrinsic factor and the terminal ileum. Damage to intestinal surface, loss of intestinal segments, or altered secretions can impair absorption even when intake is adequate. Malabsorption is therefore not synonymous with eating too little. An assessment must consider intake, digestion, absorptive capacity, and losses as separate possible contributors.'],
 ['Fed and fasting metabolism','After a meal, absorbed nutrients can supply immediate energy, build tissues, or be stored. Insulin helps coordinate nutrient use and storage. During fasting, hormonal changes support access to stored fuels and maintenance of blood glucose. Liver glycogen contributes to glucose availability, while muscle glycogen supports the muscle’s own activity. Gluconeogenesis produces glucose from noncarbohydrate precursors; glycogenolysis breaks down glycogen. Lipolysis releases fatty acids from stored triglycerides. These processes are different, even when they occur together. The body does not switch instantly from one exclusive fuel to another. Tissue needs, activity, duration of fasting, and health conditions change the mix. Metabolism includes both anabolism, building molecules, and catabolism, breaking them down. Energy balance emerges from many interacting processes rather than a single hormone alone.'],
 ['Connect mechanisms to a case','Steatorrhea refers to excess fat in stool and can suggest impaired fat digestion or absorption, but the term does not identify the exact cause. Chronic diarrhea can increase losses and affect hydration; rapid transit may reduce time for absorption. A reduced absorptive surface can lead to deficiencies of multiple nutrients. The appropriate next question is which step is disrupted, not which supplement should automatically be added. Compare an enzyme problem, a bile-related problem, and an intestinal-surface problem. Each can alter nutrient availability through a different mechanism. A learning case can support this reasoning without determining treatment. Clinical evaluation, current laboratory data, symptoms, and the person’s medical history are needed to select a nutrition intervention or diagnostic approach.']
],[['Digestion','The mechanical and chemical breakdown of food into smaller components. It is distinct from movement of those components across the intestinal lining.'],['Absorption','Transfer of nutrients from the intestinal lumen into the body. Adequate digestion does not ensure absorption if surface area or transport mechanisms are impaired.'],['Emulsification','Dispersion of fat into smaller droplets, increasing access for digestive processes. Bile supports this process but is not a protein-digesting enzyme.'],['Villi','Projections that increase intestinal absorptive surface. Damage to them can reduce nutrient uptake despite sufficient intake.'],['Portal circulation','The blood route carrying many absorbed water-soluble nutrients from intestine toward liver before they enter the wider systemic circulation.'],['Chylomicron','A lipoprotein particle packaging much absorbed dietary fat for transport through lymph and then blood. It is not an intestinal digestive enzyme.'],['Glycogenolysis','Breakdown of glycogen. It differs from gluconeogenesis, which produces new glucose from noncarbohydrate precursors.'],['Malabsorption','Impaired uptake of nutrients from the intestine. It can result from several mechanisms and is not equivalent to inadequate food availability.']],['A person has adequate food intake but damaged intestinal villi and chronic diarrhea. Explain how nutrient deficits and fluid problems can develop together.',['Damaged villi reduce absorptive surface and may impair nutrient transfer.','Unabsorbed substances can retain water in the intestine and contribute to diarrhea.','Diarrhea also removes fluid and electrolytes, so both nutrition and hydration require assessment.'],'Adequate intake cannot compensate automatically for impaired absorption. The mechanism and severity need clinical evaluation before an individualized nutrition plan is chosen.',[['Absorptive surface',['villi','surface','absorp']],['Osmotic mechanism',['water','unabsorb','osmotic']],['Losses and assessment',['electrolyte','fluid','assess']]]],[['What does bile primarily do in digestion?',['Supports fat emulsification','Breaks proteins into amino acids by itself','Produces insulin','Replaces intestinal surface area'],'Bile disperses fat and supports lipid absorption.'],['Which route carries many absorbed sugars toward the liver?',['Portal blood','Intestinal lymph as the main route for all sugars','Bile ducts carrying absorbed sugars back to the liver','Systemic arteries before any portal passage'],'Monosaccharides generally enter intestinal capillaries and portal circulation.'],['Which process creates glucose from noncarbohydrate precursors?',['Gluconeogenesis','Glycogenolysis','Emulsification','Peristalsis'],'Gluconeogenesis is distinct from releasing glucose units from glycogen.'],['Which enzyme deficiency can impair lactose digestion?',['Lactase','Pepsin','Lipase','Catalase'],'Lactase splits lactose at the intestinal brush border.']],{t:'w',kind:'order',title:'Trace a carbohydrate-containing meal',steps:['Chewing and salivary processing begin','Stomach mixing regulates delivery onward','Small-intestinal enzymes complete carbohydrate digestion','Monosaccharides cross the intestinal surface','Portal blood carries absorbed sugars toward the liver','Tissues use or store the absorbed nutrients']});

add('Vitamins: function, deficiency, excess, and evidence','A supplement contains several times the usual daily amount of a vitamin. The high number is not proof of a greater benefit. Vitamins have specific functions, and both deficiency and excess can matter.',[
 ['Vitamins help processes rather than supply calories','Vitamins are organic compounds needed in small amounts for normal physiological functions. Many support enzymes or regulation, but they do not provide food energy directly. The fat-soluble vitamins are A, D, E, and K. They are absorbed with dietary lipids and can be stored to varying degrees. Water-soluble vitamins include the B group and vitamin C. Water solubility does not guarantee that high-dose supplementation is harmless. Absorption, storage, excretion, and toxicity differ among individual vitamins. A deficiency can arise from low intake, impaired absorption, increased need, altered metabolism, or excessive loss. Therefore, a diet history is important but not sufficient to explain every low nutrient level. A symptom such as fatigue is nonspecific and should not be treated as a definitive vitamin diagnosis.'],
 ['Fat-soluble vitamins in context','Vitamin A supports vision, epithelial integrity, and immune function. Preformed vitamin A and provitamin A carotenoids differ in sources and handling. Vitamin D supports calcium regulation and bone health through several pathways; sun exposure, food, supplements, and metabolism influence status. Vitamin E contributes antioxidant functions, while vitamin K supports activation of proteins involved in coagulation and other processes. Fat malabsorption can affect this group together. Excess supplementation can cause harm, particularly when nutrients accumulate or interact with medications. A person taking an anticoagulant may need consistency and professional guidance around vitamin K rather than simply eliminating all foods that contain it. The lesson is to connect the nutrient to a function and context, not to prescribe a supplement from a single remembered association.'],
 ['B vitamins and cellular work','Thiamin participates in carbohydrate-related energy metabolism, riboflavin and niacin in oxidation-reduction reactions, and vitamin B6 in amino-acid metabolism and other functions. Folate supports one-carbon transfer and DNA synthesis, making it important in rapidly dividing tissues and early development. Vitamin B12 supports neurological function and normal blood-cell production. B12 absorption involves release from food, binding processes, intrinsic factor, and the terminal ileum. A person can therefore have a B12 problem despite apparently adequate intake. Folate and B12 deficiencies can both affect red-cell development, but their neurological implications differ. Replacing folate alone can improve some blood findings while failing to address B12-related neurological injury. This is why overlapping laboratory patterns must be interpreted carefully rather than treated as interchangeable deficiencies.'],
 ['Vitamin C and interacting nutrients','Vitamin C supports collagen synthesis and improves absorption of nonheme iron from plant sources. Severe deficiency can impair connective tissue and wound healing. Food preparation and storage can affect some vitamin content, especially for water-soluble vitamins sensitive to heat or leaching. This does not mean all cooked vegetables lack nutrients; cooking can improve safety, digestibility, and availability of some compounds. Evaluate the whole pattern. A meal combining a plant iron source with a vitamin C source demonstrates nutrient interaction without requiring a supplement. Likewise, the presence of one nutrient does not cancel every limitation of a food. A fortified beverage may supply vitamins but differ from whole foods in fiber, protein, or satiety. Nutrient claims should be read alongside actual composition and portion.'],
 ['Read intake standards and supplement claims','A recommended intake is a population-based reference intended for generally healthy people in a defined life-stage group. It is not the same as a therapeutic dose used under supervision. A tolerable upper intake level identifies an intake above which risk may rise; it is not a target to reach. Some nutrients lack an established upper limit because evidence is insufficient, not because unlimited intake is proven safe. Supplements can help in specific situations but can also interact with medications, duplicate ingredients, or distract from the cause of symptoms. Compare the active ingredient, amount per serving, and actual number of servings taken. Use reliable nutrient fact sheets and the event’s official texts to check functions, sources, deficiency patterns, and cautions rather than relying on marketing language.']
],[['Fat-soluble vitamins','Vitamins A, D, E, and K, whose absorption is linked to lipid handling. Storage and excess risks vary, so they should not be treated as identical.'],['Water-soluble vitamins','The B vitamins and vitamin C. Water solubility influences handling but does not prove that high doses are free of adverse effects.'],['Vitamin A','Supports vision and epithelial and immune functions. Preformed vitamin A and carotenoid precursors differ in handling and toxicity considerations.'],['Vitamin D','Participates in calcium regulation and bone physiology. Nutrient status depends on intake, synthesis, metabolism, and individual circumstances rather than one source alone.'],['Folate','Supports DNA synthesis and one-carbon metabolism. Its relationship to cell division explains importance during development and in blood-cell production.'],['Vitamin B12','Supports neurological function and normal blood-cell production. Adequate absorption requires a specialized pathway, so intake alone may not determine status.'],['Vitamin C','Supports collagen synthesis and enhances nonheme iron absorption. It supplies physiological support rather than calories.'],['Upper intake level','A reference boundary related to adverse-effect risk, not an intake goal. The absence of an established limit does not establish unlimited safety.']],['A learner says that fatigue proves a B-vitamin deficiency and that any water-soluble vitamin is safe in unlimited amounts. Explain why both claims are unsupported.',['Fatigue has many possible causes, and nutrient deficiency requires contextual assessment.','Water-soluble vitamins differ in handling and can cause adverse effects at excessive intakes.','A useful review considers diet, absorption, medications, symptoms, and appropriate clinical evidence.'],'Vitamin functions are specific, but symptoms are often not. Reliable intake references and evaluation are more informative than a high-dose supplement claim.',[['Nonspecific symptom',['fatigue','many','cause']],['Excess risk',['water','excess','adverse','toxic']],['Evidence and context',['absorp','medication','assess','evidence']]]],[['Which vitamin enhances nonheme iron absorption?',['Vitamin C','Vitamin K','Vitamin D','Vitamin A'],'Vitamin C can improve absorption of plant-source iron.'],['Which vitamin requires intrinsic factor for the usual absorption pathway?',['Vitamin B12','Vitamin C','Vitamin E','Thiamin'],'Intrinsic factor supports B12 absorption in the terminal ileum.'],['Which set contains only fat-soluble vitamins?',['A, D, E, K','B1, B2, B6, C','A, B12, C, K','D, folate, niacin, C'],'A, D, E, and K are the fat-soluble group.'],['How should an upper intake level be interpreted?',['As a risk-related boundary, not a target','As the minimum every person must take','As proof that higher doses work better','As the calorie content of a vitamin'],'An upper limit is not an optimal intake goal.']],{t:'w',kind:'sort',title:'Group the vitamins by solubility',buckets:['Fat-soluble','Water-soluble'],items:[['Vitamin A',0],['Vitamin D',0],['Vitamin E',0],['Vitamin K',0],['Vitamin C',1],['Thiamin',1],['Folate',1],['Vitamin B12',1]]},['NIH ODS: Vitamin B12 fact sheet','https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/']);

const extensions = [
 ['Macronutrients','Energy percentages are a different calculation from food weight percentages. A 100 g food containing 10 g fat is 10% fat by mass, but its percentage of calories from fat depends on total energy. Water can make a food heavy without adding calories, so two equally heavy foods may have very different energy density. Conversely, a small portion of a concentrated food may provide substantial energy. This distinction is useful when interpreting advertising and comparing portions. Calculate the requested quantity explicitly: grams, calories, calories per gram, and percentage of total energy answer four different questions. A correct number with the wrong unit is not a correct interpretation.'],
 ['Digestion','The large intestine also contributes to nutrition, although it is not the primary site for absorption of most macronutrients. It absorbs water and electrolytes and contains microbes that metabolize some materials reaching it. Fermentation can produce short-chain fatty acids and gas. The microbiome varies among people and can change with diet, medications, and illness, but a general claim about gut health does not establish that a particular product will treat a disease. Distinguish a demonstrated physiological function from a commercial promise. When evaluating a case, ask whether the concern is a nutrient deficit, a symptom, an altered bowel pattern, or a diagnosed disease; each requires different evidence.'],
 ['Vitamins','Laboratory interpretation also requires care. Some blood measurements reflect recent intake, while others may be influenced by inflammation, transport proteins, or organ function. A result should be interpreted with the correct reference and clinical picture rather than treated as a stand-alone explanation for every symptom. The terms deficiency, insufficiency, and toxicity have nutrient-specific definitions. A supplement containing many ingredients can duplicate nutrients already present in fortified foods or another product. Add the amounts from all relevant sources before evaluating exposure. This accounting is particularly important when the serving on the supplement label contains more than one tablet or gummy. The number of pieces taken may differ from the labeled serving.'],
 ['Minerals','Concentration and total body amount are related but different. A laboratory sodium value describes sodium relative to water in the sampled fluid; it does not directly report every gram of sodium in the body. A person can retain sodium and water yet have a low measured sodium concentration if water retention is proportionally greater. Likewise, a normal concentration does not exclude changes in total fluid volume. This is why fluid questions should specify the compartment and variable. Ask whether the problem concerns circulating volume, intracellular water, interstitial swelling, or a measured electrolyte concentration. Combining these into one vague concept of hydration can lead to contradictory conclusions.'],
 ['Nutrition during','Growth assessment should also distinguish linear growth, weight change, and body composition. A change in one measure does not explain the others. Measurements must be obtained consistently and interpreted using an appropriate reference for age and clinical circumstances. Growth velocity can reveal a concern that a single percentile misses, while a stable low or high percentile may require a different interpretation from a sudden change. Parents and caregivers may need help understanding that the goal is a healthy developmental trajectory rather than reaching one arbitrary percentile. Nutrition history, medical history, developmental skills, and the pattern over time provide the context needed for a meaningful interpretation.'],
 ['Adult nutrition','A dietary recall and a food record provide different kinds of information. A recall asks someone to reconstruct previous intake and can be affected by memory; a record captures intake prospectively but may change behavior or create burden. Neither method is perfect. Ask about usual patterns and unusual days, and avoid treating one day as a complete representation. Portion estimates, beverages, snacks, and preparation methods can be missed. The purpose is to understand opportunities and barriers, not to catch someone making a mistake. An accessible assessment method should match literacy, language, vision, cognition, and available time so that the information is as useful and respectful as possible.'],
 ['Foodborne','Cleaning and sanitizing are also distinct. Cleaning removes visible soil and residues, while sanitizing reduces microorganisms through an appropriate process. A dirty surface can interfere with a sanitizer’s effectiveness, so simply applying a chemical is not equivalent to a complete cleaning procedure. Product concentration, contact time, surface compatibility, and safe use instructions matter. Allergen removal depends on effective cleaning rather than assuming that a sanitizer destroys the relevant protein. In a food-service case, identify whether the task is removing food residue, controlling microorganisms, or preventing allergen transfer. The same surface may require attention to all three, but the explanation should name the purpose of each step.'],
 ['Medical nutrition','Risk reduction should be distinguished from an immediate treatment effect. A dietary pattern associated with improved cardiovascular outcomes over time does not act like an emergency medication during acute symptoms. Similarly, a food’s effect on one post-meal glucose measurement does not capture its entire nutritional contribution. A useful comparison considers repeated patterns and clinically relevant outcomes. Observational associations can be influenced by other behaviors and social factors, while controlled studies answer more specific questions under defined conditions. When reading a claim, identify the population, intervention, comparison, outcome, and duration. This prevents a finding about one group or short-term marker from being exaggerated into a universal recommendation.'],
 ['Renal','A nutrition diagnosis can be framed around the mechanism rather than merely repeating the disease name. For example, inadequate intake related to persistent nausea is different from altered nutrient absorption related to intestinal injury. The evidence supporting the problem might include a documented intake pattern, symptoms, or relevant measurements. The distinction matters because giving more nutrition information does not directly resolve nausea or restore damaged absorptive surface. Interventions should address the identified contributor while monitoring the consequence. In a renal case, the same principle separates excessive intake of a nutrient from impaired excretion of that nutrient. Both can affect a laboratory result, but they are not the same cause.'],
 ['Cancer','Nutrition support decisions also require attention to refeeding risk in people with substantial prolonged undernutrition. Restarting intake can produce metabolic shifts, including changes in phosphate and other electrolytes, so rapid unmonitored feeding is not automatically harmless. This concept is a reason for professional assessment and monitoring, not a reason to withhold food casually or for a student to design a refeeding schedule. The relevant history includes the duration and extent of low intake, weight and functional changes, illness, and current clinical findings. Recognizing the possibility helps explain why the route, amount, progression, and monitoring of nutrition support are coordinated by an appropriately qualified team.']
];
for (const [prefix,text] of extensions) lessons.find(l=>l.title.startsWith(prefix)).sections[4][1].push(text);
const pick = prefix => lessons.find(l => l.title.startsWith(prefix));
export default course('Nutrition', {intro:'Ten connected lessons cover the 2026–27 Nutrition blueprint: nutrients, digestion, fluid balance, lifespan and culture, food safety, and medical nutrition reasoning. Explore mechanisms and cases, then complete a written-response checkpoint. Educational examples do not prescribe an individual diet.', units:[
 {title:'Unit 1 · Nutrients, digestion, and balance',summary:'Connect food composition to absorption, metabolism, vitamins, minerals, and water.',lessons:[pick('Macronutrients'),pick('Digestion'),pick('Vitamins'),pick('Minerals')]},
 {title:'Unit 2 · Nutrition across lives and communities',summary:'Development, aging, culture, and practical access shape nutritional needs.',lessons:[pick('Nutrition during'),pick('Adult nutrition')]},
 {title:'Unit 3 · Food safety and immune reactions',summary:'Distinguish infection, toxins, allergy, and intolerance and match controls to mechanisms.',lessons:[pick('Foodborne')]},
 {title:'Unit 4 · Medical nutrition and individualized care',summary:'Reason through diabetes, cardiovascular, renal, gastrointestinal, cancer, and special-needs cases.',lessons:[pick('Medical nutrition'),pick('Renal'),pick('Cancer')]}
]});

